CREATE POLICY "Authenticated users upload own proposal PDFs" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'proposal-pdfs' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "Authenticated users view own proposal PDFs" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'proposal-pdfs' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "Authenticated users update own proposal PDFs" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'proposal-pdfs' AND (storage.foldername(name))[1] = auth.uid()::text) WITH CHECK (bucket_id = 'proposal-pdfs' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "Authenticated users delete own proposal PDFs" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'proposal-pdfs' AND (storage.foldername(name))[1] = auth.uid()::text);